<script setup>
import { computed,onMounted,ref } from 'vue'
import { api } from '../api'

const result=ref({items:[],total:0}),chapters=ref([]),points=ref([]),page=ref(0),size=ref(20),chapterId=ref(''),knowledgeId=ref(''),origin=ref(''),type=ref(''),keyword=ref(''),error=ref('')
const names={CHOICE:'单选题',FILL:'填空题',SHORT_ANSWER:'简答 / 问答题',ALGORITHM:'算法设计题'}
const visiblePoints=computed(()=>chapterId.value?points.value.filter(p=>p.chapterId===chapterId.value):points.value)
const totalPages=computed(()=>Math.max(1,Math.ceil(result.value.total/size.value)))

async function load(){try{error.value='';const query=new URLSearchParams({page:String(page.value),size:String(size.value)});for(const [key,value] of Object.entries({chapterId:chapterId.value,knowledgeId:knowledgeId.value,origin:origin.value,type:type.value,keyword:keyword.value.trim()}))if(value)query.set(key,value);result.value=await api(`/api/admin/questions?${query}`)}catch(e){error.value=e.message}}
function applyFilters(){page.value=0;load()}
function changeChapter(){if(knowledgeId.value&&!visiblePoints.value.some(p=>p.id===knowledgeId.value))knowledgeId.value='';applyFilters()}
function reset(){chapterId.value='';knowledgeId.value='';origin.value='';type.value='';keyword.value='';page.value=0;load()}
function changePage(next){if(next<0||next>=totalPages.value)return;page.value=next;load()}
onMounted(async()=>{try{[chapters.value,points.value]=await Promise.all([api('/api/admin/chapters'),api('/api/admin/knowledge-points')]);await load()}catch(e){error.value=e.message}})
</script>

<template><section><div class="page-head"><div><h2>四类题库</h2><p class="muted">按课程结构缩小范围；列表不传输答案、解析或评分要点。</p></div><RouterLink class="primary" to="/admin/questions/new">录入题目</RouterLink></div><form class="card filters" @submit.prevent="applyFilters"><label class="field">章节<select v-model="chapterId" @change="changeChapter"><option value="">全部章节</option><option v-for="chapter in chapters" :key="chapter.id" :value="chapter.id">{{chapter.code}} · {{chapter.name}}</option></select></label><label class="field">知识点<select v-model="knowledgeId" @change="applyFilters"><option value="">全部知识点</option><option v-for="point in visiblePoints" :key="point.id" :value="point.id">{{point.code}} · {{point.name}}</option></select></label><label class="field">来源<select v-model="origin" @change="applyFilters"><option value="">全部来源</option><option value="MANUAL">人工录入</option><option value="AI_GENERATED">AI 生成</option></select></label><label class="field">题型<select v-model="type" @change="applyFilters"><option value="">全部题型</option><option v-for="(label,key) in names" :key="key" :value="key">{{label}}</option></select></label><label class="field keyword">题号或题干<input v-model="keyword" placeholder="输入关键词" @keyup.esc="keyword=''" /></label><label class="field page-size">每页<select v-model.number="size" @change="applyFilters"><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select></label><div class="filter-actions"><button class="primary">搜索</button><button type="button" class="secondary" @click="reset">清空</button></div></form><div class="result-note">当前范围共 <strong>{{result.total}}</strong> 道题</div><div class="card list"><p v-if="!result.items.length" class="muted">当前筛选范围没有题目，可清空条件或录入新题。</p><RouterLink v-for="q in result.items" :key="q.id" :to="`/admin/questions/${q.id}`" class="row"><span class="code">{{q.questionNo}}</span><span class="badge">{{names[q.type]}}</span><strong>{{q.content.stem}}</strong><span>{{q.origin==='MANUAL'?'人工':'AI'}}</span><span :class="['badge',{active:q.status==='ACTIVE'}]">{{q.status==='ACTIVE'?'可用':'已下架'}}</span><small>v{{q.version}}</small></RouterLink></div><nav class="pager" aria-label="题库分页"><button class="secondary" :disabled="page===0" @click="changePage(page-1)">上一页</button><span>第 {{page+1}} / {{totalPages}} 页</span><button class="secondary" :disabled="page+1>=totalPages" @click="changePage(page+1)">下一页</button></nav><p class="error">{{error}}</p></section></template>

<style scoped>.filters{display:grid;grid-template-columns:repeat(4,minmax(140px,1fr)) minmax(200px,1.4fr) 90px auto;gap:12px;align-items:end;margin-bottom:10px}.filter-actions{display:flex;gap:8px}.result-note{margin:0 2px 10px;color:#697386;font-size:13px}.result-note strong{color:#344054;font-family:Consolas,monospace}.list{padding:8px 20px}.row{display:grid;grid-template-columns:90px 100px 1fr 55px 70px 35px;gap:12px;align-items:center;color:inherit;text-decoration:none;padding:14px 2px;border-bottom:1px solid #e8ebf0}.row:last-child{border:0}.row strong{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pager{display:flex;justify-content:center;align-items:center;gap:14px;margin-top:16px;color:#526071}.pager button:disabled{opacity:.45;cursor:not-allowed}@media(max-width:1200px){.filters{grid-template-columns:repeat(3,1fr)}.filter-actions{align-self:end}}@media(max-width:900px){.filters{grid-template-columns:1fr 1fr}.row{grid-template-columns:80px 1fr 60px}.row strong{grid-column:1/-1}.row small,.row>span:nth-last-child(2),.row>span:nth-last-child(3){display:none}}@media(max-width:600px){.filters{grid-template-columns:1fr}.filter-actions button{flex:1}}</style>
